import{_ as a,o as t,c as r,ae as s}from"./chunks/framework.RRduUuAx.js";const p=JSON.parse('{"title":"research systems","description":"","frontmatter":{"title":"research systems"},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),o={name:"index.md"};function i(l,e,n,c,h,d){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="research-systems" tabindex="-1">research systems <a class="header-anchor" href="#research-systems" aria-label="Permalink to &quot;research systems&quot;">​</a></h1><p><em>methods for knowledge and evaluation</em> Hélène Draux</p><p>This site presents methods for describing, structuring, and evaluating research systems and their outputs. It focuses on how knowledge can be represented, analysed, and tested, including under conditions of increasing automation.</p><p>The emphasis is on clarity, structure, and traceable reasoning rather than completeness.</p><p>I work at the intersection of bibliometrics, knowledge infrastructure, and AI-assisted research. This site documents that work — methods developed over several years, alongside tools and writing that sit outside the formal structure.</p><hr><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><p>Conceptual approaches for representing and analysing the structure of research systems.</p><ul><li><a href="/methods/ai-metascientist/">AI metascientist</a></li><li><a href="/methods/journalscape/">Journalscape</a></li><li><a href="/methods/writing-research-publications/">Writing research publications</a></li></ul><hr><h2 id="frameworks" tabindex="-1">Frameworks <a class="header-anchor" href="#frameworks" aria-label="Permalink to &quot;Frameworks&quot;">​</a></h2><p>Structured applications of methods in defined analytical contexts.</p><ul><li><a href="/frameworks/grid-plus/">GRID+</a></li><li><a href="/frameworks/biblioflow/">BiblioFlow</a></li><li><a href="/frameworks/dimquery/">DimQuery</a></li></ul><hr><h2 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to &quot;Tools&quot;">​</a></h2><p>Lightweight implementations supporting specific analytical tasks.</p><ul><li><a href="/tools/ava/">AVA</a></li><li><a href="/tools/url-to-dsl/">URL to DSL</a></li></ul><hr><h2 id="projects" tabindex="-1">Projects <a class="header-anchor" href="#projects" aria-label="Permalink to &quot;Projects&quot;">​</a></h2><p>Things built or written outside the formal structure — tools for personal workflows, visual and analytical experiments, work in progress.</p><ul><li><a href="/projects/loom/">Loom</a></li><li><a href="/projects/bumped-stacked-bar/">Extending Tufte: the bumped stacked bar chart</a></li><li><a href="/projects/small-multiples/">Small multiples</a></li><li><a href="/projects/claude-projects-workflows/">Claude Projects as semi-structured workflows</a></li><li><a href="/projects/vinted-semantic-layer/">Semantic layer over Vinted</a> <em>(work in progress)</em></li><li><a href="/projects/kids-voice-assistant/">Local voice assistant for kids</a></li></ul><hr><h2 id="perspective" tabindex="-1">Perspective <a class="header-anchor" href="#perspective" aria-label="Permalink to &quot;Perspective&quot;">​</a></h2><p>The work is situated within bibliometrics and research systems analysis, with a growing focus on evaluation under conditions of increasing automation.</p><p>Methods are documented at a level that supports interpretation and reuse, while full operational detail is not always public.</p><hr><h2 id="structure" tabindex="-1">Structure <a class="header-anchor" href="#structure" aria-label="Permalink to &quot;Structure&quot;">​</a></h2><p>Methods → Frameworks → Tools Conceptual → Applied → Operational</p><p>Methods inform frameworks. Frameworks organise tools.</p>',29)])])}const m=a(o,[["render",i]]);export{p as __pageData,m as default};
